import os
os.environ.setdefault("PYTORCH_ENABLE_MPS_FALLBACK", "1")

import cv2
import numpy as np

try:
    import torch
except Exception:
    torch = None


def ros_image_to_bgr(img):
    data = img.get("data") or []
    fmt = str(img.get("format") or "").lower()
    if fmt or not img.get("height"):
        try:
            arr = np.frombuffer(data, dtype=np.uint8)
        except Exception:
            arr = np.asarray(data, dtype=np.uint8)
        if arr.size <= 0:
            return None
        return cv2.imdecode(arr, cv2.IMREAD_COLOR)

    h = int(img.get("height") or 0)
    w = int(img.get("width") or 0)
    enc = str(img.get("encoding") or "rgb8").lower()
    if h <= 0 or w <= 0:
        return None
    channels = 3
    if enc == "mono8":
        channels = 1
    if enc in {"rgba8", "bgra8"}:
        channels = 4
    try:
        arr = np.frombuffer(data, dtype=np.uint8)
    except Exception:
        arr = np.asarray(data, dtype=np.uint8)
    needed = h * w * channels
    if arr.size < needed:
        return None
    arr = arr[:needed].reshape((h, w, channels))
    if enc == "rgb8":
        return cv2.cvtColor(arr, cv2.COLOR_RGB2BGR)
    if enc == "rgba8":
        return cv2.cvtColor(arr, cv2.COLOR_RGBA2BGR)
    if enc == "bgra8":
        return cv2.cvtColor(arr, cv2.COLOR_BGRA2BGR)
    if enc == "mono8":
        return cv2.cvtColor(arr, cv2.COLOR_GRAY2BGR)
    return arr.copy()


def bgr_to_ros_image(bgr):
    if bgr is None:
        return None
    if len(bgr.shape) == 2:
        rgb = cv2.cvtColor(bgr, cv2.COLOR_GRAY2RGB)
    else:
        rgb = cv2.cvtColor(bgr, cv2.COLOR_BGR2RGB)
    rgb = np.ascontiguousarray(rgb, dtype=np.uint8)
    h, w = rgb.shape[:2]
    return {
        "height": int(h),
        "width": int(w),
        "encoding": "rgb8",
        "is_bigendian": 0,
        "step": int(w * 3),
        "data": rgb.tobytes(),
    }


def select_torch_device(prefer="auto"):
    prefer = str(prefer or "auto").lower()
    if torch is not None:
        if prefer == "cuda":
            try:
                if torch.cuda.is_available():
                    return "cuda"
            except Exception:
                pass
            return "cpu"
        if prefer == "mps":
            try:
                if torch.backends.mps.is_available():
                    return "mps"
            except Exception:
                pass
        try:
            if torch.cuda.is_available():
                return "cuda"
        except Exception:
            pass
        try:
            if torch.backends.mps.is_available():
                return "mps"
        except Exception:
            pass
    return "cpu"


def midas_bundle(state, model_type="DPT_Hybrid", prefer_device="auto"):
    key = "midas:" + str(model_type) + ":" + str(prefer_device)
    bundle = state.get(key)
    if bundle is not None:
        return bundle
    if torch is None:
        raise RuntimeError("torch is required for MiDaS")
    device_name = select_torch_device(prefer_device)
    device = torch.device(device_name if device_name != "mps" else "mps")
    model = torch.hub.load("intel-isl/MiDaS", model_type, trust_repo=True)
    model.to(device).eval()
    transforms = torch.hub.load("intel-isl/MiDaS", "transforms", trust_repo=True)
    transform = transforms.dpt_transform if model_type.startswith("DPT") else transforms.small_transform
    state[key] = (model, transform, device)
    if not state.get("device_logged"):
        state["device_logged"] = True
        print("MiDaS device:", device_name)
    return state[key]


def midas_depth_overlay(state, img, model_type="DPT_Hybrid", prefer_device="auto"):
    bgr = ros_image_to_bgr(img)
    if bgr is None:
        return None
    rgb = cv2.cvtColor(bgr, cv2.COLOR_BGR2RGB)
    model, transform, device = midas_bundle(state, model_type, prefer_device)
    input_batch = transform(rgb).to(device)
    with torch.no_grad():
        prediction = model(input_batch)
        prediction = torch.nn.functional.interpolate(
            prediction.unsqueeze(1),
            size=rgb.shape[:2],
            mode="bicubic",
            align_corners=False,
        ).squeeze()
    depth = prediction.detach().cpu().numpy()
    norm = cv2.normalize(depth, None, 0, 255, cv2.NORM_MINMAX).astype(np.uint8)
    color = cv2.applyColorMap(norm, cv2.COLORMAP_INFERNO)
    return bgr_to_ros_image(color)
